use verus::prelude::*;

/// Returns the index of the last (rightmost) occurrence of the maximum value in a non-empty slice.
/// 
/// # Panics
///
/// Panics if `v` is empty.
#[verifier::requires(v.len() > 0)]
#[verifier::ensures(|res: usize|
    // the result is in‐bounds
    res < v.len()
    // v[res] is indeed the maximum over the whole slice
    && forall(|i: usize| i < v.len() ==> v[i] <= v[res])
    // and no element to the right is equal to v[res], so `res` is the last occurrence
    && forall(|j: usize| res < j && j < v.len() ==> v[j] < v[res])
)]
pub fn last_max_index(v: &[i32]) -> usize {
    // we keep `max_idx` pointing to the last‐seen maximum in v[0..i)
    let mut max_idx: usize = 0;
    let mut i: usize = 1;
    while i < v.len() {
        //–– loop invariants ––
        #[verifier::invariant(i <= v.len())]
        #[verifier::invariant(max_idx <= i)]
        #[verifier::invariant(forall(|j: usize| j < i ==> v[j] <= v[max_idx]))]
        #[verifier::invariant(
            forall(|j: usize| j < i && v[j] == v[max_idx] ==> j <= max_idx)
        )]
        #[verifier::decreases(v.len() - i)]
        {
            // if we see an element >= the current max, update so that
            // we record the rightmost such index
            if v[i] > v[max_idx] || v[i] == v[max_idx] {
                max_idx = i;
            }
            i += 1;
        }
        max_idx
    }
}

